function option(x:string,locale:NativeLocale):string{
 const a=x.match(/^Article\s+(243[A-O]?|244)$/);if(a)return (locale==="hi"?"अनुच्छेद ":"ਅਨੁਛੇਦ ")+a[1];
 const yrs=x.match(/^(18|21|25|30) years$/);if(yrs)return yrs[1]+(locale==="hi"?" वर्ष":" ਸਾਲ");
 if(/^(18|22|29|30)$/.test(x))return x;
 const z=O[x];if(z)return z[locale];
 throw new Error("POL-CP-019 missing localized option: "+x);
}
